INPUTS = {'photo captions/Trip 00.TXT': 'Caption for frame 00\n', 'photo captions/Trip 01.TXT': 'Caption for frame 01\n', 'photo captions/Trip 02.TXT': 'Caption for frame 02\n', 'photo captions/Trip 03.TXT': 'Caption for frame 03\n', 'photo captions/Trip 04.TXT': 'Caption for frame 04\n', 'photo captions/Trip 05.TXT': 'Caption for frame 05\n', 'photo captions/Trip 06.TXT': 'Caption for frame 06\n', 'photo captions/Trip 07.TXT': 'Caption for frame 07\n', 'photo captions/Trip 08.TXT': 'Caption for frame 08\n', 'photo captions/Trip 09.TXT': 'Caption for frame 09\n', 'photo captions/Trip 10.TXT': 'Caption for frame 10\n', 'photo captions/Trip 11.TXT': 'Caption for frame 11\n', 'photo captions/already.txt': 'existing lower case\n', 'photo captions/album/sub.TXT': 'nested caption\n', 'photo captions/notes.TXT.bak': 'archive note\n'}
import json, hashlib, re, shutil, subprocess, sys, tempfile
from pathlib import Path
SCRIPT = Path(__file__).resolve().parents[1] / 'scripts/rename_captions.sh'
BASE = len(sys.argv) > 1 and sys.argv[1] == 'base'
def put(p, text):
    p = root / p
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')
def get(p):
    return (root / p).read_bytes().decode('utf-8')
def tree(p):
    base = root / p
    return {str(f.relative_to(base)): f.read_bytes().decode('utf-8') for f in base.rglob('*') if f.is_file()}
def run(*args, code=0):
    run.calls = getattr(run, 'calls', 0) + 1
    relative = run.calls % 2 == 0
    actual = [str(value) if relative or not (i in (0,)) else str(root / str(value)) for i, value in enumerate(args)]
    r = subprocess.run(['bash', str(SCRIPT), *actual], cwd=root, capture_output=True, text=True, timeout=10)
    assert r.returncode == code, (args, r.returncode, r.stdout, r.stderr)
    return r
with tempfile.TemporaryDirectory(prefix='ops-check-') as temporary:
    root = Path(temporary) / 'work area'
    root.mkdir()
    for p, text in INPUTS.items():
        put(p, text)
    before=tree('photo captions')
    run('photo captions')
    want={(p[:-4]+'.txt' if '/' not in p and p.endswith('.TXT') else p):v for p,v in before.items()}
    assert tree('photo captions') == want
    run('photo captions');assert tree('photo captions') == want
    (root/'empty captions').mkdir();run('empty captions');assert tree('empty captions') == {}
    put('different directory/中文 标题.TXT','一行\n');run('different directory')
    assert tree('different directory') == {'中文 标题.txt':'一行\n'}
    put('hidden captions/.private.TXT','private\n')
    (root/'hidden captions/directory.TXT').mkdir()
    run('hidden captions')
    assert tree('hidden captions') == {'.private.txt':'private\n'}
    assert (root/'hidden captions/directory.TXT').is_dir()

